<?php
declare(strict_types=1);
namespace OMT;
require_once __DIR__.'/documents.php';
final class Pg {
 public const TEMPLATES=['reminder'=>'om_tiffin_pg_fee_reminder','receipt'=>'om_tiffin_pg_payment_receipt'];
 public function __construct(private readonly Store $store,private readonly array $settings=[]){}
 public static function today():string{return (new \DateTimeImmutable('now',new \DateTimeZone('Asia/Kolkata')))->format('Y-m-d');}
 private static function month(string $v):string{if(!preg_match('/^20\d{2}-(0[1-9]|1[0-2])$/D',$v))throw new HttpError(400,'Choose a valid month');return $v;}
 private static function money(mixed $v):int{if(!is_numeric($v)||!is_finite((float)$v)||$v<0||$v>1000000)throw new HttpError(400,'Enter a valid amount');return (int)round((float)$v*100);}
 public static function due(string $m,int $d):string{return $m.'-'.str_pad((string)min($d,(int)(new \DateTimeImmutable($m.'-01'))->format('t')),2,'0',STR_PAD_LEFT);}
 public static function cycle(string $month,int $day):array {
  $anchor=new \DateTimeImmutable($month.'-01');$start=$day===1?$month.'-01':self::due($anchor->modify('-1 month')->format('Y-m'),$day);
  $next=$day===1?$anchor->modify('+1 month')->format('Y-m-d'):self::due($month,$day);
  return ['periodStart'=>$start,'periodEnd'=>(new \DateTimeImmutable($next))->modify('-1 day')->format('Y-m-d'),'dueDate'=>$start];
 }
 public static function feeMonth(string $start):string{$d=new \DateTimeImmutable($start);return (int)$d->format('j')===1?$d->format('Y-m'):$d->modify('first day of next month')->format('Y-m');}
 private function upgradeCycles():void {
  foreach($this->store->all('pgstudents')as $student){if(isset($student['firstCycleStart']))continue;
   $first=self::due($student['startMonth'],$student['reminderDay']);$student['firstCycleStart']=$first;$student['startMonth']=self::feeMonth($first);$student['cycleVersion']=2;$student['revision']++;$this->store->put('pgstudents',$student);
   foreach($this->store->find('pgcharges',fn($c)=>$c['student']===$student['_id']&&!isset($c['periodStart']))as $c){
    if($c['paidPaise']>0)continue;$start=$c['dueDate'];$c['month']=self::feeMonth($start);$c=array_replace($c,self::cycle($c['month'],$student['reminderDay']));$this->store->put('pgcharges',$c);$this->store->put('pgaudit',['action'=>'cycle-upgrade','student'=>$student['_id'],'charge'=>$c['_id'],'periodStart'=>$c['periodStart'],'periodEnd'=>$c['periodEnd'],'feeMonth'=>$c['month']],true);
    foreach($this->store->find('pgnotifications',fn($n)=>$n['charge']===$c['_id'])as $n){$n['month']=$c['month'];$this->store->put('pgnotifications',$n);}
   }
  }
 }
 private function ensureFee(array $s,string $month):array {
  if($existing=$this->store->first('pgcharges',fn($c)=>$c['student']===$s['_id']&&$c['month']===$month))return $existing;
  return $this->store->put('pgcharges',array_merge(['_id'=>substr(hash('sha256','pg:'.$s['_id'].':'.$month),0,24),'student'=>$s['_id'],'month'=>$month,'feePaise'=>$s['monthlyFeePaise'],'paidPaise'=>0,'revision'=>1],self::cycle($month,$s['reminderDay'])),true);
 }
 public function prepareFee(string $id,array $b):array{return $this->store->transaction(function()use($id,$b){$this->store->preparePgCollections();$this->upgradeCycles();$s=$this->student($id);$month=self::month((string)($b['month']??''));$max=(new \DateTimeImmutable(self::today()))->modify('+2 years')->format('Y-m');if(!$s['active']||$month<$s['startMonth']||$month>$max)throw new HttpError(400,'Choose an active student fee month within the next two years');return success($this->ensureFee($s,$month));});}
 public function student(string $id):array{return $this->store->get('pgstudents',$id)??throw new HttpError(404,'Student not found');}
 public function save(array $b,string $actor,?string $id=null):array{return $this->store->transaction(function()use($b,$actor,$id){$this->store->preparePgCollections();$this->upgradeCycles();$old=$id?$this->student($id):null;if(!$old&&isset($b['firstCycleStart'])){$first=(string)$b['firstCycleStart'];$parsed=\DateTimeImmutable::createFromFormat('!Y-m-d',$first);if(!$parsed||$parsed->format('Y-m-d')!==$first)throw new HttpError(400,'Choose a valid first cycle date');$b['reminderDay']=(int)$parsed->format('j');$b['startMonth']=self::feeMonth($first);}if($old&&(int)($b['reminderDay']??0)!==$old['reminderDay'])throw new HttpError(409,'The cycle day is fixed after creation to preserve fee periods');if($old&&($b['revision']??null)!==$old['revision'])throw new HttpError(409,'Refresh before editing');if(!is_string($b['name']??null)||!is_string($b['phone']??null))throw new HttpError(400,'Enter name and mobile as text');$name=trim($b['name']);$phone=preg_replace('/\D/','',(string)($b['phone']??''));if(strlen($phone)===10)$phone='91'.$phone;$day=$b['reminderDay']??0;if(!$name||mb_strlen($name)>100||!preg_match('/^[1-9][0-9]{10,14}$/D',$phone)||!is_numeric($day)||(int)$day!=$day||$day<1||$day>31)throw new HttpError(400,'Enter name, mobile and reminder day 1–31');foreach(['active','messagesEnabled']as $k)if(!is_bool($b[$k]??null))throw new HttpError(400,'Choose ON or OFF');$start=self::month((string)($b['startMonth']??''));if($old&&$start!==$old['startMonth'])throw new HttpError(409,'Start month cannot change');if($start<substr(self::today(),0,4).'-01'&&$start<(new \DateTimeImmutable(self::today()))->modify('-5 years')->format('Y-m'))throw new HttpError(400,'Choose a start month within five years');$fee=self::money($b['monthlyFee']??null);if(!$fee)throw new HttpError(400,'Fee must be positive');$s=$this->store->put('pgstudents',array_replace($old??[],['firstCycleStart'=>$old['firstCycleStart']??($b['firstCycleStart']??self::cycle($start,(int)$day)['periodStart']),'cycleVersion'=>2,'name'=>$name,'phone'=>$phone,'monthlyFeePaise'=>$fee,'reminderDay'=>(int)$day,'startMonth'=>$start,'active'=>$b['active'],'messagesEnabled'=>$b['messagesEnabled'],'revision'=>($old['revision']??0)+1]),!$old);$this->store->put('pgaudit',['actor'=>$actor,'student'=>$s['_id'],'before'=>$old,'after'=>$s],true);return success($s);});}
 public function sync(?string $today=null):void{$today??=self::today();$this->store->transaction(function()use($today){$this->store->preparePgCollections();$this->upgradeCycles();foreach($this->store->all('pgstudents')as $s){if(!$s['active'])continue;$m=$s['startMonth'];$limit=(new \DateTimeImmutable(substr($today,0,7).'-01'))->modify('+1 month')->format('Y-m');$n=0;while($m<=$limit){if(++$n>120)throw new HttpError(400,'Start month too old');if(self::cycle($m,$s['reminderDay'])['periodStart']<=$today)$this->ensureFee($s,$m);$m=(new \DateTimeImmutable($m.'-01'))->modify('+1 month')->format('Y-m');}}});}
 public function listing(array $q):array {
  $selection=(string)($q['month']??'current');if($selection!=='current')self::month($selection);$today=self::today();$month=substr($today,0,7);$students=$this->store->all('pgstudents');$target=[];
  foreach($students as &$s){$selected=$selection;if($selection==='current'){$selected=$s['reminderDay']>1&&$today>=self::due($month,$s['reminderDay'])?(new \DateTimeImmutable($month.'-01'))->modify('+1 month')->format('Y-m'):$month;$selected=max($selected,$s['startMonth']);}$target[$s['_id']]=$selected;$s['selectedFeeMonth']=$selected;$s=array_replace($s,self::cycle($selected,$s['reminderDay']));}unset($s);
  return success(['students'=>$students,'charges'=>$this->store->find('pgcharges',fn($c)=>isset($target[$c['student']])&&$c['month']===$target[$c['student']]),'payments'=>$this->store->find('pgpayments',fn($c)=>isset($target[$c['student']])&&$c['month']===$target[$c['student']]),'messages'=>$this->store->find('pgnotifications',fn($c)=>isset($target[$c['student']])&&$c['month']===$target[$c['student']]),'templates'=>self::TEMPLATES]);
 }
 public function payment(string $cid,array $b,string $actor):array{$key=(string)($b['requestId']??'');if(!preg_match('/^[a-f0-9-]{36}$/Di',$key))throw new HttpError(400,'Refresh and retry');return $this->store->transaction(function()use($cid,$b,$actor,$key){$this->store->preparePgCollections();$id=substr(hash('sha256','pg-payment:'.$key),0,24);$amount=self::money($b['amount']??null);$hash=hash('sha256',json_encode([$cid,$amount,$b['method']??'',$b['date']??'',$b['reference']??'']));if($p=$this->store->get('pgpayments',$id)){if($hash!==$p['fingerprint'])throw new HttpError(409,'Request already used');return success($p);}$c=$this->store->get('pgcharges',$cid)??throw new HttpError(404,'Fee not found');$s=$this->student($c['student']);if(!$s['active']||$amount<=0||$amount>$c['feePaise']-$c['paidPaise'])throw new HttpError(400,'Payment must not exceed pending fee');$date=(string)($b['date']??'');$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date||$date>self::today())throw new HttpError(400,'Invalid payment date');$method=$b['method']??'';if(!in_array($method,['Cash','UPI','Bank transfer'],true))throw new HttpError(400,'Invalid payment method');$ref=trim((string)($b['reference']??''));if(mb_strlen($ref)>200)throw new HttpError(400,'Reference too long');$c['paidPaise']+=$amount;$c['revision']++;$this->store->put('pgcharges',$c);$p=$this->store->put('pgpayments',['_id'=>$id,'student'=>$s['_id'],'charge'=>$cid,'month'=>$c['month'],'periodStart'=>$c['periodStart']??null,'periodEnd'=>$c['periodEnd']??null,'amountPaise'=>$amount,'date'=>$date,'method'=>$method,'reference'=>$ref,'receiptNo'=>'PG-'.str_replace('-','',$date).'-'.strtoupper(substr($id,-8)),'snapshot'=>['name'=>$s['name'],'phone'=>$s['phone'],'feePaise'=>$c['feePaise'],'paidAfterPaise'=>$c['paidPaise'],'pendingAfterPaise'=>$c['feePaise']-$c['paidPaise']],'fingerprint'=>$hash,'actor'=>$actor],true);$this->enqueue('receipt',$s,$c,$p);return success($p);});}
 private function enqueue(string $type,array $s,array $c,?array $p=null):void{if(!$s['messagesEnabled'])return;$key='pg:'.$type.':'.($p['_id']??$c['_id']);$id=substr(hash('sha256',$key),0,24);if($this->store->get('pgnotifications',$id))return;$this->store->put('pgnotifications',['_id'=>$id,'student'=>$s['_id'],'charge'=>$c['_id'],'month'=>$c['month'],'payment'=>$p['_id']??null,'type'=>$type,'whatsappStatus'=>'pending','eventKey'=>$key],true);$this->store->queue($key,['kind'=>'pg-notification','notificationId'=>$id,'notificationType'=>$type,'to'=>$s['phone'],'templateName'=>self::TEMPLATES[$type],'languageCode'=>'en_GB']);}
 public function reminders(?string $today=null):void{$today??=self::today();$this->sync($today);$this->store->transaction(function()use($today){foreach($this->store->all('pgcharges')as $c){if(substr($c['dueDate'],0,7)!==substr($today,0,7)||$c['dueDate']>$today||$c['paidPaise']>=$c['feePaise'])continue;$s=$this->student($c['student']);if($s['active'])$this->enqueue('reminder',$s,$c);}});}
 public function statuses():array{return success(['reminder'=>$this->templateStatus('reminder'),'receipt'=>$this->templateStatus('receipt')]);}
 public function templateStatus(string $type):string{$id=$this->settings[$type==='receipt'?'PG_RECEIPT_TEMPLATE_ID':'PG_REMINDER_TEMPLATE_ID']??($type==='reminder'?'1132726936406473':'1133624312439153');$token=$this->settings['WHATSAPP_ACCESS_TOKEN']??'';$v=$this->settings['WHATSAPP_API_VERSION']??'v26.0';if(!$id||!$token||!ctype_digit((string)$id)||!preg_match('/^v\d+\.\d+$/D',$v)||!function_exists('curl_init'))return 'NOT_CONFIGURED';$h=curl_init('https://graph.facebook.com/'.$v.'/'.$id.'?fields=name,language,status,category');curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>5,CURLOPT_CONNECTTIMEOUT=>2,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token]]);$raw=curl_exec($h);$http=curl_getinfo($h,CURLINFO_RESPONSE_CODE);curl_close($h);$d=is_string($raw)?json_decode($raw,true):[];return $http===200&&($d['name']??'')===self::TEMPLATES[$type]&&($d['language']??'')==='en_GB'&&($d['category']??'')==='UTILITY'?($d['status']??'UNKNOWN'):'UNKNOWN';}
 public function prepare(array $p):?array{$n=$this->store->get('pgnotifications',$p['notificationId'])??throw new \RuntimeException('Missing message');$s=$this->student($n['student']);$c=$this->store->get('pgcharges',$n['charge'])??throw new \RuntimeException('Missing fee');if(!$s['active']||!$s['messagesEnabled']||$p['to']!==$s['phone'])return null;$month=(new \DateTimeImmutable($c['month'].'-01'))->format('F Y').(isset($c['periodStart'])?' ('.$c['periodStart'].' to '.$c['periodEnd'].')':'');if($n['type']==='receipt'){$r=$this->store->get('pgpayments',$n['payment']);$values=[$r['snapshot']['name'],number_format($r['amountPaise']/100,2,'.',''),$month,$r['receiptNo'],$r['date'],number_format($r['snapshot']['pendingAfterPaise']/100,2,'.','')];$pdf=$this->receipt($r['_id'])[1];require_once __DIR__.'/document-notifications.php';$p['kind']='document-template';$p['attachment']=(new DocumentNotifications($this->store,new Documents($this->store)))->storePdf($pdf->bytes);$p['filename']=$pdf->filename;}else{if($c['paidPaise']>=$c['feePaise']||substr($c['dueDate'],0,7)!==substr(self::today(),0,7))return null;$values=[$s['name'],$month,number_format(($c['feePaise']-$c['paidPaise'])/100,2,'.',''),$c['dueDate']];}$p['components']=[['type'=>'body','parameters'=>array_map(fn($v)=>['type'=>'text','text'=>(string)$v],$values)]];return $p;}
 public function receipt(string $id):array{$p=$this->store->get('pgpayments',$id)??throw new HttpError(404,'Receipt not found');$designs=(new Documents($this->store))->settings()[1]['data'];$design=$designs['pg'];return [200,new PdfResponse((new PdfRenderer())->run(['type'=>'pg','data'=>$p,'design'=>$design]),$p['receiptNo'].'.pdf')];}
}
